package com.progressly.activity.security;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.nio.charset.StandardCharsets; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Configuration @EnableWebSecurity public class JwtSecurity { @Bean SecurityFilterChain filterChain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).exceptionHandling(e->e.authenticationEntryPoint((q,r,x)->write(r,401,"AUTHENTICATION_REQUIRED","Authentication is required")).accessDeniedHandler((q,r,x)->write(r,403,"ACCESS_DENIED","You do not have permission for this resource"))).authorizeHttpRequests(a->a.requestMatchers("/api/v1/health","/actuator/**","/swagger-ui/**","/swagger-ui.html","/v3/api-docs/**").permitAll().anyRequest().authenticated()).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();} private static void write(HttpServletResponse r,int status,String code,String message)throws java.io.IOException{r.setStatus(status);r.setContentType("application/json");r.getWriter().write("{\"status\":"+status+",\"error\":\""+code+"\",\"message\":\""+message+"\"}");} }
@Component class JwtFilter extends OncePerRequestFilter { private final SecretKey key; JwtFilter(@Value("${progressly.security.jwt-secret}")String s){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse p,FilterChain c)throws java.io.IOException,ServletException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var x=Jwts.parser().verifyWith(key).build().parseSignedClaims(h.substring(7)).getPayload();var a=new UsernamePasswordAuthenticationToken(x.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+x.get("role",String.class))));org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}catch(RuntimeException ignored){}c.doFilter(r,p);} }
